(async () => {
  const { accessSync } = await import('node:fs');
  const input = process.env.INPUT_PATH;
  const output = process.env.OUTPUT_PATH;
  if (!input) throw new Error('Missing INPUT_PATH');
  if (!output) throw new Error('Missing OUTPUT_PATH');
  try { accessSync(input); } catch { throw new Error('Input file not found'); }
  globalThis.inputPath = input;
  globalThis.outputPath = output;
  const w = process.env.WIDTH ? parseInt(process.env.WIDTH, 10) : null;
  const h = process.env.HEIGHT ? parseInt(process.env.HEIGHT, 10) : null;
  globalThis.width = w;
  globalThis.height = h;
})();

(async () => {
  const sharpMod = await import('sharp');
  const sharp = sharpMod.default || sharpMod;
  if (typeof sharp !== 'function') throw new Error('sharp export not a function');
  const img = sharp(globalThis.inputPath);
  const resizeOpts = {};
  if (globalThis.width !== null) resizeOpts.width = globalThis.width;
  if (globalThis.height !== null) resizeOpts.height = globalThis.height;
  await img.resize(resizeOpts).toFile(globalThis.outputPath);
  globalThis.resultPath = globalThis.outputPath;
})();
